// Handle n8n HTTP text response
const rawInput = $input.first().json;
const csvText = typeof rawInput.data === 'string' ? rawInput.data
  : typeof rawInput.body === 'string' ? rawInput.body
  : typeof rawInput === 'string' ? rawInput
  : null;

if (csvText) {
  const lines = csvText.split(/\r?\n/).filter(Boolean);
  if (!lines.length) return [];
  const headers = lines.shift().split(',').map(h => h.trim().replace(/^"|"$/g, ''));
  const leads = lines.map(line => {
    const values = line.split(',').map(v => v.trim().replace(/^"|"$/g, ''));
    const row = {};
    headers.forEach((h, i) => row[h] = values[i] || '');
    return row;
  }).filter(r => r.organization_name || r.company || r.entreprise);

  const source = Object.assign({}, $('Set CRM Growth Config').first().json, { leads });
  return leads.map((row, index) => ({ json: canonicalize(row, index) }));
}

const source = $("Set CRM Growth Config").first().json;
function slugify(value) {
  return String(value || '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}
function domainFromWebsite(website) {
  return String(website || '').replace(/^https?:\/\//i, '').replace(/^www\./i, '').split('/')[0].trim();
}
function pickFirst() {
  for (const value of arguments) {
    if (value === undefined || value === null) continue;
    if (String(value).trim() === '') continue;
    return String(value).trim();
  }
  return '';
}
function normalizeWebsite(value) {
  const website = String(value || '').trim();
  if (!website) return '';
  return /^https?:\/\//i.test(website) ? website : `https://${website}`;
}
function canonicalize(row, index) {
  const website = normalizeWebsite(pickFirst(row.website, row.domain, row.site_web, row.website_url));
  const domain = domainFromWebsite(website);
  const organizationName = pickFirst(row.organization_name, row.company_name, row.company, row.companyName, row.societe, row.entreprise, row.organisation, row.name);
  const decisionMakerName = pickFirst(row.decision_maker_name, row.contact_name, row.contact, row.full_name, row.nom_complet, row.nom, row.prenom_nom) || 'Décideur à confirmer';
  const targetEmail = pickFirst(row.target_email, row.email, row.email_address, row.adresse_email, row.courriel);
  const leadOrigin = pickFirst(row.lead_origin, row.form_source, row.form_name, row.lead_source, source.ingest_label) || 'public_scrape';
  return {
    prospect_id: row.prospect_id || `crm-${slugify(domain || organizationName || 'lead')}-${index + 1}`,
    organization_name: organizationName,
    website,
    country: pickFirst(row.country, row.pays) || source.default_country || "Côte d'Ivoire",
    organization_type: pickFirst(row.organization_type, row.type_organisation, row.account_type) || source.default_organization_type || 'organisation à qualifier',
    sector_guess: pickFirst(row.sector_guess, row.industry, row.secteur, row.sector) || source.default_sector_guess || 'secteur à confirmer',
    decision_maker_name: decisionMakerName,
    target_email: targetEmail,
    custom_page_paths_csv: pickFirst(row.custom_page_paths_csv, row.pages_cibles_csv),
    booking_link_45min: pickFirst(row.booking_link_45min, row.booking_link, row.calendly_link) || $env.BOOKING_LINK_45MIN || '',
    commercial_priority_default: pickFirst(row.commercial_priority_default, row.priority, row.priority_tier),
    research_scope: pickFirst(row.research_scope, row.portee_recherche) || source.default_research_scope || 'public_web_only',
    lead_origin: leadOrigin,
    source_backend: source.crm_backend || 'supabase',
    raw_source_id: row.raw_source_id || row.id || domain || null
  };
}
if (Array.isArray(source.leads)) {
  return source.leads.map((row, index) => ({ json: canonicalize(row || {}, index) }));
}
if (typeof source.body === 'string' || typeof source.data === 'string') {
  const raw = String(source.body || source.data || '');
  const lines = raw.split(/\r?\n/).filter(Boolean);
  if (!lines.length) return [];
  const headers = lines.shift().split(',').map((h) => h.trim());
  return lines.map((line, index) => {
    const values = line.split(',');
    const row = {};
    headers.forEach((header, idx) => row[header] = (values[idx] || '').trim());
    return { json: canonicalize(row, index) };
  });
}
if (source.body && typeof source.body === 'object' && Array.isArray(source.body.leads)) {
  return source.body.leads.map((row, index) => ({ json: canonicalize(row || {}, index) }));
}
return [{ json: canonicalize(source, 0) }];

const lead = $json;
const config = $('Set CRM Growth Config').first().json || {};
const delayDays = Number(config.next_action_delay_days || 1);
const hasEmail = Boolean(String(lead.target_email || '').trim());
const hasWebsite = Boolean(String(lead.website || '').trim());
const hasSector = Boolean(String(lead.sector_guess || '').trim());
const hasDecisionMaker = Boolean(String(lead.decision_maker_name || '').trim()) && String(lead.decision_maker_name || '').trim().toLowerCase() !== 'décideur à confirmer';
const origin = String(lead.lead_origin || '').toLowerCase();
const explicitHighIntent = /(audit|demo|rdv|meeting|appointment|contact|google\s*form|inbound)/i.test(origin);
let derivedPriority = String(lead.commercial_priority_default || '').trim().toLowerCase();
if (!derivedPriority) {
  if (explicitHighIntent || (hasEmail && hasWebsite && hasSector && hasDecisionMaker)) {
    derivedPriority = 'tier1';
  } else if (hasEmail && hasWebsite) {
    derivedPriority = 'tier2';
  } else {
    derivedPriority = 'tier3';
  }
}
const nextActionAt = lead.next_action_at || new Date(Date.now() + (derivedPriority === 'tier1' ? 0 : delayDays) * 86400000).toISOString();
return [{
  json: {
    ...lead,
    commercial_priority_default: derivedPriority,
    status: hasEmail ? 'ready' : 'draft',
    paused: false,
    do_not_contact: false,
    outreach_attempt_count: Number(lead.outreach_attempt_count || 0),
    last_response_status: lead.last_response_status || '',
    last_sequence_result: lead.last_sequence_result || '',
    stop_reason: hasEmail ? '' : 'missing_target_email',
    niche_status: lead.niche_status || (hasEmail ? `pre_scored_${derivedPriority}` : 'needs_email_enrichment'),
    next_action_at: nextActionAt,
    updated_at: new Date().toISOString()
  }
}];

const imported = items.map((item) => item.json);
const config = $('Set CRM Growth Config').first().json;
const readyCount = imported.filter((row) => row.status === 'ready').length;
const draftCount = imported.filter((row) => row.status === 'draft').length;
const tierBreakdown = imported.reduce((acc, row) => {
  const key = String(row.commercial_priority_default || 'unknown');
  acc[key] = (acc[key] || 0) + 1;
  return acc;
}, {});
return [{
  json: {
    imported_count: imported.length,
    imported_ready_count: readyCount,
    imported_draft_count: draftCount,
    priority_breakdown: tierBreakdown,
    imported_prospect_ids: imported.map((row) => row.prospect_id || row[0]?.prospect_id).filter(Boolean),
    dispatch_to_v4: config.dispatch_to_v4,
    child_workflow_id_v4: config.child_workflow_id_v4,
    child_workflow_id_v3: config.child_workflow_id_v3,
    child_workflow_label_v3: config.child_workflow_label_v3,
    batch_fetch_limit: config.batch_fetch_limit,
    daily_send_limit: config.daily_send_limit,
    max_attempts_per_prospect: config.max_attempts_per_prospect,
    min_confidence_score: config.min_confidence_score,
    batch_run_label: config.batch_run_label,
    booking_link_45min: config.booking_link_45min,
    ingest_label: config.ingest_label
  }
}];

const crmRows = Array.isArray($json) ? $json : Array.isArray($json.data) ? $json.data : [];
let outreachRows = [];
try {
  const snap = $('Fetch Today Outreach Snapshot').first().json;
  outreachRows = Array.isArray(snap) ? snap : Array.isArray(snap.data) ? snap.data : [];
} catch (e) {}
const importSummary = $('Build CRM Import Summary').first().json;
return [{
  json: {
    crm_stage: 'v5_growth_loop_completed',
    imported_count: importSummary.imported_count || 0,
    crm_ready_count: crmRows.length,
    outreach_today_count: outreachRows.length,
    dispatch_to_v4: importSummary.dispatch_to_v4,
    child_workflow_id_v4: importSummary.child_workflow_id_v4 || null,
    child_workflow_id_v3: importSummary.child_workflow_id_v3 || null,
    child_workflow_label_v3: importSummary.child_workflow_label_v3 || null,
    batch_fetch_limit: importSummary.batch_fetch_limit || null,
    daily_send_limit: importSummary.daily_send_limit || null,
    next_step: importSummary.dispatch_to_v4 ? 'V4 batch can now process the CRM queue with the configured V3 enhanced workflow.' : 'CRM queue updated without dispatch.',
    generated_at: new Date().toISOString()
  }
}];
